<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('quotes.delete');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}verify_csrf();$id=(int)($_POST['id']??0);$stmt=db()->prepare('SELECT quotation_number,client_id FROM quotations WHERE id=?');$stmt->execute([$id]);$q=$stmt->fetch();if($q){db()->prepare('DELETE FROM quotations WHERE id=?')->execute([$id]);log_activity('Cotización eliminada',(int)$q['client_id'],null,$q['quotation_number']);flash('success','Cotización eliminada.');}redirect('quotations.php');
